 "content": "def transform(grid):
    """Fill rectangular frames; turn the center of a 3x3 color-6 frame to 7."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    colors = set(v for row in grid for v in row if v != background)

    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                     if r in (r0, r1) or c in (c0, c1)}
        if set(cells) != perimeter:
            continue
        if color == 6 and r1 - r0 == 2 and c1 - c0 == 2:
            out[r0 + 1][c0 + 1] = 7
        else:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    out[r][c] = 2
    return out
