 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                         if y in (r0, r1) or x in (c0, c1)}
            if comp == perimeter:
                ih, iw = r1-r0-1, c1-c0-1
                fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
                for y in range(r0+1, r1):
                    for x in range(c0+1, c1):
                        out[y][x] = fill
    return out
